{
  "meta": {
    "title": "Token bucket in a shared store",
    "topicClass": "concept",
    "format": "full",
    "targetLengthSec": 70
  },
  "story": {
    "devices": [
      "versus_split",
      "planted_question",
      "real_incident",
      "spec_card_ending"
    ],
    "hook": {
      "kind": "problem"
    },
    "runningExample": "One free-tier API key sends a burst of checkout requests through the gateway; every request spends a token from the same bucket in the shared store.",
    "chapters": [
      {
        "id": "ch-meltdown",
        "title": "Checkout meltdown"
      },
      {
        "id": "ch-bucket",
        "title": "Token bucket"
      },
      {
        "id": "ch-shared",
        "title": "Shared store"
      },
      {
        "id": "ch-incident",
        "title": "What broke"
      },
      {
        "id": "ch-fix",
        "title": "The fix"
      }
    ],
    "beats": [
      {
        "id": "b1",
        "chapterId": "ch-meltdown",
        "intent": "A routine failover makes the limiter's shared store call jump to 80 ms, and 31% of checkout requests fail.",
        "targetSec": 7,
        "factIds": [
          "fact-19",
          "fact-20",
          "fact-18"
        ],
        "hookNumberIds": [
          "num-16",
          "num-15"
        ],
        "layoutMode": "centered_focus"
      },
      {
        "id": "b2",
        "chapterId": "ch-bucket",
        "intent": "Show a fixed window counting requests per calendar minute, then the boundary trick sends the whole quota twice for 2× the limit.",
        "device": "versus_split",
        "targetSec": 8,
        "factIds": [
          "fact-9",
          "fact-10",
          "num-7"
        ],
        "newTerms": [
          "Fixed window"
        ],
        "layoutMode": "versus_split",
        "suggestedPatternIds": [
          "versus_split"
        ]
      },
      {
        "id": "b3",
        "chapterId": "ch-bucket",
        "intent": "Replace the window with a token bucket whose 100-token capacity and 10/s refill bound bursts to the capacity no matter where the clock is.",
        "device": "planted_question",
        "targetSec": 8,
        "factIds": [
          "fact-1",
          "fact-3",
          "num-1",
          "num-2"
        ],
        "newTerms": [
          "Token bucket"
        ],
        "continuesPrevious": true
      },
      {
        "id": "b4",
        "chapterId": "ch-shared",
        "intent": "Put the bucket in one shared store and run the read, compute and write as one indivisible operation; otherwise 24 gateway nodes give a caller 24 times the limit.",
        "targetSec": 10,
        "factIds": [
          "fact-7",
          "fact-6",
          "num-3",
          "num-4"
        ],
        "newTerms": [
          "Shared store"
        ],
        "layoutMode": "hub_spoke"
      },
      {
        "id": "b5",
        "chapterId": "ch-shared",
        "intent": "Show every request paying a network round trip to the shared store — 0.4 ms median — with a 50 ms store timeout waiting to trip.",
        "targetSec": 8,
        "factIds": [
          "fact-8",
          "fact-15",
          "num-5",
          "num-13"
        ],
        "continuesPrevious": true
      },
      {
        "id": "b6",
        "chapterId": "ch-incident",
        "intent": "A failover moves the store to another zone, calls jump to 80 ms, the limiter stops enforcing the shared limit and checks locally on every instance; 31% of checkouts fail.",
        "device": "real_incident",
        "targetSec": 12,
        "factIds": [
          "fact-19",
          "fact-20",
          "fact-18",
          "num-16",
          "num-15"
        ],
        "layoutMode": "pipeline",
        "source": "Larkspur Pay post-incident report, 14 March 2025"
      },
      {
        "id": "b7",
        "chapterId": "ch-fix",
        "intent": "For the payment-provider route, refuse uncounted traffic, divide local fallback limits by instance count, and raise the store timeout to 150 ms so cross-zone latency does not trip it.",
        "targetSec": 10,
        "factIds": [
          "fact-23",
          "num-20"
        ],
        "continuesPrevious": true
      },
      {
        "id": "b8",
        "chapterId": "ch-fix",
        "intent": "Close on the three-line spec card and a share line asking viewers to follow for the next system design.",
        "device": "spec_card_ending",
        "targetSec": 7,
        "factIds": [],
        "layoutMode": "centered_focus"
      }
    ],
    "plantedQuestion": {
      "text": "Why does every gateway have to check the same bucket in a shared store?",
      "beatId": "b3",
      "payoffBeatId": "b6"
    },
    "rejectedAlternative": {
      "beatId": "b2",
      "summary": "A fixed window lets a client send its whole quota at the end of one minute and the start of the next, reaching up to 2× the limit across the boundary.",
      "chosenBeatId": "b3"
    },
    "ending": {
      "kind": "spec_card_ending",
      "cta": "Share this with a teammate who thinks per-instance limits are enough, and follow for the next system design.",
      "specCard": {
        "lines": [
          "One shared token bucket",
          "Atomic read-compute-write",
          "Fail closed when store slow"
        ]
      }
    },
    "missingPrimitiveRequests": []
  }
}

